import { test, expect } from '@playwright/test';

test.describe('Sidebar Collapse and Expand Functionality', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('/dashboard');
  });

  test('should collapse and expand the sidebar on click', async ({ page }) => {
    // Verify sidebar is visible by default
    const sidebar = page.getByRole('navigation');
    await expect(sidebar).toBeVisible();

    // Verify sidebar has correct initial state
    const sidebarState = page.getByRole('status', { name: /collapsed/i });
    await expect(sidebarState).toBeVisible();

    // Click the sidebar toggle button to collapse
    const toggleButton = page.getByRole('button', { name: /toggle sidebar/i });
    await toggleButton.click();

    // Verify sidebar is now collapsed
    await expect(sidebar).not.toBeVisible();

    // Verify status message indicates collapsed state
    await expect(sidebarState).toContainText(/collapsed/i);

    // Click the toggle button again to expand
    await toggleButton.click();

    // Verify sidebar is now visible
    await expect(sidebar).toBeVisible();

    // Verify status message indicates expanded state
    await expect(sidebarState).toContainText(/expanded/i);

    // Verify sidebar content is accessible
    const sidebarContent = page.getByRole('navigation', { name: /dashboard/i });
    await expect(sidebarContent).toBeVisible();

    // Verify sidebar menu items are visible
    const menuItem = page.getByRole('link', { name: /settings/i });
    await expect(menuItem).toBeVisible();

    // Verify sidebar menu items are clickable
    await expect(menuItem).toBeEnabled();
  });

  test('should handle edge case: clicking outside sidebar', async ({ page }) => {
    // Verify sidebar is visible
    const sidebar = page.getByRole('navigation');
    await expect(sidebar).toBeVisible();

    // Verify sidebar is expanded
    const sidebarState = page.getByRole('status', { name: /expanded/i });
    await expect(sidebarState).toBeVisible();

    // Click outside the sidebar to trigger collapse
    const outsideElement = page.locator('body');
    await outsideElement.click();

    // Verify sidebar collapses
    await expect(sidebar).not.toBeVisible();

    // Verify status message indicates collapsed state
    await expect(sidebarState).toContainText(/collapsed/i);

    // Verify sidebar content is still accessible
    const sidebarContent = page.getByRole('navigation', { name: /dashboard/i });
    await expect(sidebarContent).toBeVisible();

    // Verify sidebar menu items are still visible
    const menuItem = page.getByRole('link', { name: /settings/i });
    await expect(menuItem).toBeVisible();

    // Verify sidebar menu items are still clickable
    await expect(menuItem).toBeEnabled();
  });
});
